-- Save MJ: Application Settings (core SP call only)
DECLARE @ID_428c4346838f UNIQUEIDENTIFIER,
@ApplicationID_428c4346838f UNIQUEIDENTIFIER,
@Name_428c4346838f NVARCHAR(100),
@Value_428c4346838f NVARCHAR(MAX),
@Comments_428c4346838f NVARCHAR(MAX)
SET
  @ID_428c4346838f = 'E0E1703F-EB3F-4FE9-A5EA-B7472F433FC2'
SET
  @ApplicationID_428c4346838f = 'FB80FEB4-5505-49D1-93CE-2E7BD030B478'
SET
  @Name_428c4346838f = N'OrderReviewTriggers'
SET
  @Value_428c4346838f = N''
SET
  @Comments_428c4346838f = N'Comma-separated order review triggers that are switched on (bc-aidp-next-golive#320 section 5): any of NoDeal, PriceVariance, ChangedAfterDealOrReview, OverThreshold, ServicePeriod. A Direct order that hits one cannot confirm until the reviewer role approves its review task. Empty switches review off, so orders confirm as before. An entry that names no trigger refuses every reviewed confirm until it is corrected.'
SELECT TOP 1 @ApplicationID_428c4346838f = [ID] FROM [${mjSchema}].[Application] WHERE [Name] = N'__mj_BizAppsOrders' ORDER BY CASE WHEN [ID] = @ApplicationID_428c4346838f THEN 0 ELSE 1 END
IF NOT EXISTS (SELECT 1 FROM [${mjSchema}].[ApplicationSetting]
               WHERE [ID] = @ID_428c4346838f
                  OR ([ApplicationID] = @ApplicationID_428c4346838f AND [Name] = @Name_428c4346838f))
EXEC [${mjSchema}].spCreateApplicationSetting @ID = @ID_428c4346838f,
  @ApplicationID = @ApplicationID_428c4346838f,
  @Name = @Name_428c4346838f,
  @Value = @Value_428c4346838f,
  @Comments = @Comments_428c4346838f;

GO

