  @Value_781d88cd4b40 = N''
SET
  @Comments_781d88cd4b40 = N'The amount at or below which a refund may be issued by a holder of the RefundApproverRole role (bc-aidp-next-golive#320). Above it, only the receiving company''s approver (ApprovalCFOUserID on its Accounting Company Profile) may issue the refund. The amount compared is what the payment''s refunds come to with the new one, so a refund cannot be split to pass. It is counted per payment, not per order: an order settled by three 400 payments under a 500 threshold can be fully refunded, 1200, by a role holder taking one payment at a time. The company approver may always refund; a deactivated approver counts as none. A refund the payment gateway already made, booked by the system user, is exempt. Empty, the default, switches the check off. A value that is not a number of 0 or more is read as 0, so every refund needs the company approver.'
SELECT TOP 1 @ApplicationID_781d88cd4b40 = [ID] FROM [${mjSchema}].[Application] WHERE [Name] = N'__mj_BizAppsOrders' ORDER BY CASE WHEN [ID] = @ApplicationID_781d88cd4b40 THEN 0 ELSE 1 END
IF NOT EXISTS (SELECT 1 FROM [${mjSchema}].[ApplicationSetting]
               WHERE [ID] = @ID_781d88cd4b40
                  OR ([ApplicationID] = @ApplicationID_781d88cd4b40 AND [Name] = @Name_781d88cd4b40))
EXEC [${mjSchema}].spCreateApplicationSetting @ID = @ID_781d88cd4b40,
  @ApplicationID = @ApplicationID_781d88cd4b40,
  @Name = @Name_781d88cd4b40,
  @Value = @Value_781d88cd4b40,
  @Comments = @Comments_781d88cd4b40;

GO

